// THE CORE PROBLEM DSA SOLVES
// Task: check whether a value exists in a collection

// Without DSA knowledge
function containsValue_naive(arr, target) {
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === target) return true;
    }
    return false;
}
// Time: O(n) per lookup. With 1,000,000 items: up to 1,000,000 comparisons.

// With DSA knowledge: right data structure for the right problem
const valueSet = new Set(arr);          // build once: O(n)
function containsValue_dsa(target) {
    return valueSet.has(target);        // O(1) per lookup, always
}
// 1,000,000 items = exactly 1 operation per lookup regardless of size

// At scale with 1M items and 1M lookups:
// Naive:   up to 1,000,000,000,000 operations (could take minutes)
// DSA:     1,000,000 operations     (milliseconds)
// This gap is the difference between a feature that works and a production outage.

// HOW ARRAYS LIVE IN MEMORY
// Array starts at address 1000. Each JS number = 8 bytes (64-bit float).
const scores = [88, 92, 75, 96];
// Address 1000: 88
// Address 1008: 92
// Address 1016: 75
// Address 1024: 96

// scores[2]:
// CPU computes: 1000 + (2 x 8) = 1016
// Reads address 1016 directly -> 75
// One arithmetic operation + one memory read. Always O(1).

// HOW LINKED LISTS LIVE IN MEMORY
// Nodes can be anywhere, connected only by pointers
// Node at 1000: { value: 88, next: 2500 }
// Node at 2500: { value: 92, next: 4100 }
// Node at 4100: { value: 75, next: null }
// To reach value 75 (3rd node):
// Read 1000 -> follow pointer to 2500
// Read 2500 -> follow pointer to 4100
// Read 4100 -> value is 75
// Three reads for index 2. In general: O(n) reads for index n.

// CACHE EFFECT (invisible in Big O, very visible in benchmarks)
// Array traversal: CPU loads a block of consecutive bytes into cache
for (let i = 0; i < scores.length; i++) {
    // Each access: cache HIT -> ~1 nanosecond
}
// Linked list traversal: pointers jump to scattered memory addresses
// Each next pointer: cache MISS -> ~100-300 nanoseconds
// Result: arrays benchmark 3-10x faster even at identical Big O

// OPERATION COUNTING STEP BY STEP

// Example 1: single loop
function sumArray(arr) {              // n = arr.length
    let total = 0;                    // 1 op
    for (let i = 0; i < arr.length; i++) { // n iterations
        total += arr[i];              //   2 ops: array read + addition
    }
    return total;                     // 1 op
}
// Raw count: 1 + 2n + 1 = 2n + 2
// Dominant term: n  ->  Big O: O(n)

// Example 2: nested loops, both scale with n
function allPairs(arr) {              // n = arr.length
    for (let i = 0; i < arr.length; i++) {          // n iterations
        for (let j = i + 1; j < arr.length; j++) {  // ~n iterations
            console.log(arr[i], arr[j]);             //   1 op
        }
    }
}
// Raw count: n x (n-1)/2 ~= n^2/2
// Dominant term: n^2  ->  Big O: O(n^2)

// Example 3: inner loop is FIXED, not n-dependent
function fixedInner(arr) {
    for (let i = 0; i < arr.length; i++) {  // n iterations
        for (let j = 0; j < 5; j++) {        // always exactly 5
            console.log(arr[i], j);
        }
    }
}
// Raw count: 5n
// Dominant term: n  ->  Big O: O(n)  NOT O(n^2)
// The inner loop is constant, not n-dependent. This is the most common mistake.

// O(1) constant: same time regardless of n
const getFirst  = arr => arr[0];                  // O(1)
const mapLookup = (map, k) => map.get(k);         // O(1)

// O(log n) logarithmic: input halves every step
function binarySearch(arr, target) {
    let left = 0, right = arr.length - 1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] === target) return mid;
        arr[mid] < target ? left = mid + 1 : right = mid - 1;
    }
    return -1;
}
// 1,000,000 sorted items -> at most log2(1,000,000) = 20 steps

// O(n) linear: one full pass
function findMax(arr) {
    let max = arr[0];
    for (const num of arr) if (num > max) max = num;
    return max;
}

// O(n^2) quadratic: nested loops both scale with n
function hasDuplicate_brute(arr) {
    for (let i = 0; i < arr.length; i++)
        for (let j = i + 1; j < arr.length; j++)
            if (arr[i] === arr[j]) return true;
    return false;
}
// Can we do better? Yes: trade O(n) space for O(n) time

// O(n) time using a hash set
function hasDuplicate_optimal(arr) {
    const seen = new Set();
    for (const num of arr) {
        if (seen.has(num)) return true;  // O(1) lookup
        seen.add(num);                   // O(1) insert
    }
    return false;
}
// Brute:   O(n^2) time | O(1) space
// Optimal: O(n)   time | O(n) space  <- classic time-space tradeoff

// O(1) SPACE: fixed memory regardless of n
function findMax(arr) {
    let max = arr[0];       // one variable only
    for (const num of arr) if (num > max) max = num;
    return max;
}
// Time: O(n)  |  Space: O(1)

// O(n) SPACE: extra memory grows with input
function twoSum(nums, target) {
    const seen = new Map();     // up to n entries -> O(n) space
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        if (seen.has(complement)) return [seen.get(complement), i];
        seen.set(nums[i], i);
    }
    return [];
}
// Time: O(n)  |  Space: O(n)  [Map holds up to n entries]
// Tradeoff: O(n) space buys us O(n) time instead of O(n^2)

// RECURSION STACK SPACE: the most commonly forgotten source
function factorial(n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);  // n frames alive simultaneously at deepest point
}
// factorial(5) call stack at maximum depth:
//   factorial(5) waits for factorial(4)
//   factorial(4) waits for factorial(3)
//   factorial(3) waits for factorial(2)
//   factorial(2) waits for factorial(1)  <- deepest: 5 frames alive
// Time: O(n)  |  Space: O(n)  [call stack, NOT a data structure]

// ALWAYS STATE BOTH IN AN INTERVIEW:
// findMax:   Time O(n) | Space O(1)
// twoSum:    Time O(n) | Space O(n)
// factorial: Time O(n) | Space O(n) [call stack depth]

// LINEAR SEARCH: all three cases
function linearSearch(arr, target) {
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === target) return i;  // early exit on match
    }
    return -1;
}
// Best case:    O(1)   target is arr[0], exits immediately
// Average case: O(n/2) = O(n)  target at random position in middle on average
// Worst case:   O(n)   target at last index or not present
// Interview default: O(n)  [worst case unless asked otherwise]

// EARLY EXIT IMPROVING EFFECTIVE AVERAGE CASE
function processIfEligible(data, key) {
    if (!data.has(key)) return null;       // O(1) guard: 95% of calls exit here
    return heavyComputation(data.get(key)); // O(n): only 5% of calls reach here
}
// Worst case:    O(n)  [key exists, heavy work runs]
// Average case:  O(1)  [95% of real calls hit the guard and return immediately]
// Production behaviour is dominated by average case, not worst case

// QUICKSORT: why average case justifies production use
// Worst case:    O(n^2)     on sorted input with first-element pivot
// Average case:  O(n log n) on random input with randomised pivot
// Best case:     O(n log n) on perfect pivot choices
// Solution: randomise pivot selection -> worst case becomes astronomically unlikely
// This is why V8, Python's Timsort, and most production sort implementations use it

// SIMULATION: verify amortized O(1) push empirically
function simulateDynamicArray(n) {
    let capacity = 1;
    let size = 0;
    let totalCopies = 0;

    for (let i = 0; i < n; i++) {
        if (size === capacity) {
            totalCopies += size;   // cost of resize: copy all current elements
            capacity *= 2;         // CRITICAL: double, not increment by 1
        }
        size++;                    // push: O(1) when no resize
    }

    const ratio = (totalCopies / n).toFixed(3);
    console.log(`n=${n} | total copies=${totalCopies} | ratio=${ratio}`);
    // ratio converges to 2 regardless of n -> amortized cost = O(1)
}

simulateDynamicArray(16);
// n=16 | total copies=15 | ratio=0.938
simulateDynamicArray(1000);
// n=1000 | total copies=1984 | ratio=1.984
simulateDynamicArray(1000000);
// n=1000000 | total copies=1999999 | ratio=2.000
// Ratio approaches exactly 2 as n grows -> amortized cost per push = O(1)

// CONTRAST: grow by 1 instead of doubling
function simulateSlow(n) {
    let capacity = 1, size = 0, totalCopies = 0;
    for (let i = 0; i < n; i++) {
        if (size === capacity) { totalCopies += size; capacity += 1; } // +1 not x2
        size++;
    }
    console.log(`slow: n=${n} | copies=${totalCopies} | ratio=${(totalCopies/n).toFixed(1)}`);
}
simulateSlow(1000);
// slow: n=1000 | copies=499500 | ratio=499.5  -> O(n) amortized, catastrophic

// FACTORIAL: frame-by-frame call stack trace
function factorial(n) {
    if (n <= 1) return 1;              // BASE CASE: n=1 or n=0
    return n * factorial(n - 1);       // RECURSIVE CASE: smaller problem
}

// factorial(4) execution trace:
// PUSH: factorial(4)  -> waiting for factorial(3)
//   PUSH: factorial(3)  -> waiting for factorial(2)
//     PUSH: factorial(2)  -> waiting for factorial(1)
//       PUSH: factorial(1)  -> base case -> returns 1
//     POP:  factorial(2)  -> computes 2 * 1 = 2 -> returns 2
//   POP:  factorial(3)  -> computes 3 * 2 = 6 -> returns 6
// POP:  factorial(4)  -> computes 4 * 6 = 24 -> returns 24
// Time: O(n)  |  Space: O(n) [4 frames alive simultaneously at deepest point]

// FIBONACCI: introduces overlapping subproblems (foundation of Level 2 DP)
function fib(n) {
    if (n <= 1) return n;             // base cases: fib(0)=0, fib(1)=1
    return fib(n - 1) + fib(n - 2);  // two recursive branches
}
// fib(5) partial call tree:
//               fib(5)
//          fib(4)    fib(3)
//       fib(3) fib(2)  fib(2) fib(1)
// fib(2) computed 3 times. fib(3) computed twice. Redundant work.
// Time: O(2^n)  |  Space: O(n) call stack depth
// Level 2 Module 1: cache fib(2) and fib(3) -> O(n) time with memoisation

// MISSING BASE CASE: stack overflow
function broken(n) {
    return n * broken(n - 1);         // no base case -> infinite recursion
    // RangeError: Maximum call stack size exceeded
}

// PROBLEM: Given an array of integers and a target sum, return
// the indices of the two numbers that add to the target.
// Exactly one valid answer exists.

// STEP 1: CLARIFY
// Q: Can the same element be used twice? -> No, different indices required.
// Q: Are inputs always valid integers? -> Yes.
// Q: Is the array sorted? -> Not guaranteed.
// Q: Can the array be empty? -> No, exactly one solution is guaranteed.

// STEP 2: EXAMPLES (created independently)
// [2, 7, 11, 15], target=9  -> [0, 1]  (2+7=9)
// [3, 2, 4],     target=6  -> [1, 2]  (2+4=6)
// [3, 3],        target=6  -> [0, 1]  (3+3=6, same value, different indices)

// STEP 3: BRUTE FORCE
// Check every pair. O(n^2) time, O(1) space.
function twoSum_brute(nums, target) {
    for (let i = 0; i < nums.length; i++)
        for (let j = i + 1; j < nums.length; j++)
            if (nums[i] + nums[j] === target) return [i, j];
}

// STEP 4: OPTIMISE
// Bottleneck: for each element, searching the rest takes O(n) time.
// Pattern: hash map gives O(1) lookup for the complement.
// Question to ask: 'Have I seen (target - current) before?'
function twoSum_optimal(nums, target) {
    const seen = new Map();
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        if (seen.has(complement)) return [seen.get(complement), i];
        seen.set(nums[i], i);
    }
}

// STEP 5: TEST
// twoSum_optimal([2,7,11,15], 9) -> [0,1]  check
// twoSum_optimal([3,2,4], 6)     -> [1,2]  check
// twoSum_optimal([3,3], 6)       -> [0,1]  check (duplicate values handled)
// Time: O(n) | Space: O(n)
// Improvement: O(n^2) -> O(n) time by trading O(1) -> O(n) space

